import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';

function CommunityEssay() {
  const [tailwindLoaded, setTailwindLoaded] = useState(false);
  const [editMode, setEditMode] = useStorage('essay-edit-mode', false, { scope: 'user' });
  const [essayContent, setEssayContent] = useStorage('essay-content', getDefaultEssay(), { scope: 'user' });
  const [wordCount, setWordCount] = useState(0);

  useEffect(() => {
    if (!document.getElementById('tailwind-script')) {
      const tailwindScript = document.createElement('script');
      tailwindScript.id = 'tailwind-script';
      tailwindScript.src = 'https://cdn.tailwindcss.com';
      tailwindScript.onload = () => {
        setTimeout(() => setTailwindLoaded(true), 100);
      };
      document.head.appendChild(tailwindScript);
    } else {
      setTailwindLoaded(true);
    }
  }, []);

  useEffect(() => {
    document.body.style.background = '#ffffff';
    document.documentElement.style.minHeight = '100%';
    return () => { 
      document.body.style.background = ''; 
      document.documentElement.style.minHeight = ''; 
    };
  }, []);

  useEffect(() => {
    const words = essayContent.trim().split(/\s+/).filter(w => w.length > 0);
    setWordCount(words.length);
  }, [essayContent]);

  if (!tailwindLoaded) {
    return (
      <div style={{ 
        padding: '60px', 
        textAlign: 'center', 
        fontFamily: 'Inter, Helvetica, sans-serif',
        color: '#9ca3af'
      }}>
        Loading...
      </div>
    );
  }

  return (
    <div style={{ fontFamily: 'Inter, Helvetica, sans-serif' }} className="min-h-screen bg-white">
      <div className="max-w-3xl mx-auto px-8 py-16">
        {/* Header */}
        <div className="mb-12">
          <div className="flex items-center justify-between mb-6">
            <span className="text-xs font-medium tracking-widest text-gray-400 uppercase">
              College Application Essay
            </span>
            <div className="flex items-center gap-4">
              <span className="text-xs text-gray-400">
                {wordCount} words
              </span>
              <button
                onClick={() => setEditMode(!editMode)}
                className="px-4 py-2 text-xs font-medium rounded-lg transition-all duration-200"
                style={{
                  background: editMode ? '#4F46E5' : '#fafafa',
                  color: editMode ? '#ffffff' : '#6b7280',
                  border: editMode ? 'none' : '1px solid #f0f0f0'
                }}
              >
                {editMode ? 'Save' : 'Edit'}
              </button>
            </div>
          </div>

          <h1 className="text-3xl font-semibold text-gray-900 mb-3 leading-tight">
            Community Influence
          </h1>

          <p className="text-gray-400 text-sm leading-relaxed">
            We all contribute to, and are influenced by, the communities that are meaningful to us. 
            Share how you've been shaped by one of the communities you belong to.
          </p>
        </div>

        {/* Divider */}
        <div className="w-16 h-px bg-gray-200 mb-12"></div>

        {/* Essay Content */}
        <div className="mb-16">
          {editMode ? (
            <textarea
              value={essayContent}
              onChange={(e) => setEssayContent(e.target.value)}
              className="w-full min-h-[600px] text-gray-700 text-base leading-relaxed resize-none focus:outline-none p-6 rounded-xl"
              style={{
                background: '#fafafa',
                border: '1px solid #f0f0f0',
                fontFamily: 'Inter, Helvetica, sans-serif'
              }}
              placeholder="Write your essay here..."
            />
          ) : (
            <div className="prose prose-gray max-w-none">
              {essayContent.split('\n\n').map((paragraph, index) => (
                <p 
                  key={index} 
                  className="text-gray-700 text-base leading-relaxed mb-6"
                  style={{ textIndent: index > 0 ? '2em' : '0' }}
                >
                  {paragraph}
                </p>
              ))}
            </div>
          )}
        </div>

        {/* Footer */}
        <div 
          className="pt-8"
          style={{ borderTop: '1px solid #f0f0f0' }}
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-sm font-medium text-gray-900">Olakunle D. Ajani</p>
              <p className="text-xs text-gray-400 mt-1">Northwestern Private Christian College, Class of 2029</p>
            </div>
            <div className="text-right">
              <p className="text-xs text-gray-400">lime17451@gmail.com</p>
              <p className="text-xs text-gray-400">(443) 891-5273</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function getDefaultEssay() {
  return `The fluorescent lights of Room 214 flickered as I stared at the wreckage of our robot—a tangled mess of servos, aluminum, and three months of sleepless weekends. Our first regional competition was in six days, and our autonomous navigation system had just fried itself during a test run. As president of the Glen Burnie High School Robotics Club, I had two choices: accept defeat or rally a team that was already running on fumes.

I chose neither. Instead, I chose to listen.

That night, I called an emergency meeting. Rather than presenting solutions, I asked each of the fourteen members to share what they believed went wrong and what they would do differently. Marcus, our quietest freshman, suggested we had overcomplicated the circuit design. Destiny, who had joined robotics to fulfill a graduation requirement, pointed out that we had been so focused on impressive features that we had neglected basic reliability. Their insights weren't revolutionary, but they were honest—and honesty, I realized, was exactly what our club had been missing.

The Robotics Club became my community not because I led it, but because it transformed how I understood leadership itself. When I first took over as president sophomore year, I believed leadership meant having all the answers. I would arrive at meetings with detailed agendas, predetermined solutions, and little patience for deviation. Our club functioned, but it didn't thrive. Members completed tasks but rarely proposed ideas. We built robots that worked but never exceeded expectations.

The broken robot changed everything. In those six days before competition, I watched our club evolve from a hierarchy into a true collaborative community. We divided into specialized teams—not because I assigned them, but because members naturally gravitated toward their strengths. The engineering pathway training from my BMAH program helped me facilitate technical discussions, but it was the collective intelligence of our community that solved the problem. We rebuilt our robot from scratch, simplifying the design while improving functionality.

We placed seventh at regionals—not a trophy-worthy finish, but a victory nonetheless. More importantly, I witnessed fourteen individuals become a genuine community, united not by my direction but by shared purpose and mutual respect.

This experience reshaped every community I've touched since. When I founded the Sports Analyst Club, I began not with my vision but with questions: What do you want to learn? What problems do you see? How can we solve them together? When volunteering with Fem Equity, I learned to direct people not by commanding but by empowering. Even my small e-commerce venture, Solitaire.org, operates on principles I learned in that robotics room—collaboration over control, listening over lecturing.

The Robotics Club taught me that communities are not built by leaders who have all the answers, but by leaders who ask the right questions. My role is not to solve every problem but to create spaces where others feel safe contributing their unique perspectives. Whether I'm helping pack diapers at Chick-fil-A Leadership Academy or managing team members at my IT internship, I carry this understanding with me.

Now, as I prepare for college, I don't aspire to join communities where I can demonstrate expertise. I seek communities where I can continue learning the art of collective problem-solving—where my background in engineering, entrepreneurship, and athletics can contribute to something larger than myself. The fluorescent lights of Room 214 still flicker in my memory, not as a reminder of failure, but as a testament to what happens when a community truly comes together.`;
}

export default CommunityEssay;

import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';

// Generate random hex color
const randomColor = () => {
  const letters = '0123456789ABCDEF';
  let color = '#';
  for (let i = 0; i < 6; i++) {
    color += letters[Math.floor(Math.random() * 16)];
  }
  return color;
};

// Preset color palettes with 4 colors each
const PRESET_PALETTES = [
  { name: 'Ocean Breeze', colors: ['#667eea', '#764ba2', '#f093fb', '#4facfe'] },
  { name: 'Sunset Glow', colors: ['#fa709a', '#fee140', '#30cfd0', '#330867'] },
  { name: 'Forest Dream', colors: ['#134e5e', '#71b280', '#134e5e', '#71b280'] },
  { name: 'Candy Pop', colors: ['#f857a6', '#ff5858', '#feca57', '#ee5a6f'] },
  { name: 'Northern Lights', colors: ['#00d2ff', '#3a7bd5', '#00d2ff', '#928dab'] },
  { name: 'Peachy Keen', colors: ['#ed4264', '#ffedbc', '#f7971e', '#ffd200'] },
  { name: 'Midnight City', colors: ['#232526', '#414345', '#0f2027', '#2c5364'] },
  { name: 'Berry Fusion', colors: ['#9796f0', '#fbc7d4', '#f38181', '#aa076b'] },
  { name: 'Emerald Wave', colors: ['#348f50', '#56b4d3', '#348f50', '#56b4d3'] },
  { name: 'Lavender Sky', colors: ['#a8edea', '#fed6e3', '#d299c2', '#fef9d7'] },
  { name: 'Citrus Burst', colors: ['#f83600', '#f9d423', '#ff8008', '#ffc837'] },
  { name: 'Deep Purple', colors: ['#673ab7', '#512da8', '#d500f9', '#aa00ff'] },
  { name: 'Coral Reef', colors: ['#ff6b6b', '#4ecdc4', '#45b7d1', '#f7b731'] },
  { name: 'Arctic Frost', colors: ['#e0eafc', '#cfdef3', '#a1c4fd', '#c2e9fb'] },
  { name: 'Crimson Tide', colors: ['#eb3349', '#f45c43', '#fa709a', '#fee140'] }
];

function CssGradientGenerator() {
  const [tailwindLoaded, setTailwindLoaded] = useState(false);
  const [fontsLoaded, setFontsLoaded] = useState(false);

  // Gradient state - now using an array of color stops
  const [gradientType, setGradientType] = useState('linear');
  const [colorStops, setColorStops] = useState([
    { id: 1, color: randomColor(), position: 0 },
    { id: 2, color: randomColor(), position: 100 }
  ]);
  const [angle, setAngle] = useState(90);
  const [copied, setCopied] = useState(false);
  const [previewMode, setPreviewMode] = useState(false);
  const [activeStop, setActiveStop] = useState(null);
  const [isDragging, setIsDragging] = useState(false);

  // Dropdown state
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const dropdownRef = useRef(null);
  const gradientBarRef = useRef(null);
  const draggingIdRef = useRef(null);

  // Palette panel state
  const [palettePanelOpen, setPalettePanelOpen] = useState(true);

  useEffect(() => {
    if (!document.getElementById('tailwind-script')) {
      const tailwindScript = document.createElement('script');
      tailwindScript.id = 'tailwind-script';
      tailwindScript.src = 'https://cdn.tailwindcss.com';
      tailwindScript.onload = () => {
        setTimeout(() => setTailwindLoaded(true), 100);
      };
      document.head.appendChild(tailwindScript);
    } else {
      setTailwindLoaded(true);
    }
  }, []);

  // Load Playfair Display font
  useEffect(() => {
    if (!document.getElementById('playfair-font')) {
      const link = document.createElement('link');
      link.id = 'playfair-font';
      link.rel = 'stylesheet';
      link.href = 'https://fonts.googleapis.com/css2?family=Playfair+Display:wght@400;500;600;700&display=swap';
      link.onload = () => setFontsLoaded(true);
      document.head.appendChild(link);
    } else {
      setFontsLoaded(true);
    }
  }, []);

  // Set dark background
  useEffect(() => {
    document.body.style.background = '#0a0a0a';
    document.body.style.margin = '0';
    document.body.style.padding = '0';
    document.body.style.overflow = 'hidden';
    document.documentElement.style.height = '100%';
    return () => {
      document.body.style.background = '';
      document.body.style.margin = '';
      document.body.style.padding = '';
      document.body.style.overflow = '';
      document.documentElement.style.height = '';
    };
  }, []);

  // Close dropdown on click outside
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Generate inverted color
  const invertColor = (hex) => {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    const inverted = `#${(255 - r).toString(16).padStart(2, '0')}${(255 - g).toString(16).padStart(2, '0')}${(255 - b).toString(16).padStart(2, '0')}`;
    return inverted;
  };

  // Generate gradient CSS with overlap handling
  const gradientCSS = useMemo(() => {
    const sortedStops = [...colorStops].sort((a, b) => a.position - b.position);

    let processedStops = [];

    // Group overlapping stops (within 2% of each other)
    let i = 0;
    while (i < sortedStops.length) {
      const current = sortedStops[i];

      // Find all stops that overlap with current (within 2%)
      let groupEnd = i;
      while (groupEnd + 1 < sortedStops.length && 
             sortedStops[groupEnd + 1].position - current.position <= 2) {
        groupEnd++;
      }

      if (groupEnd > i) {
        // // Multiple stops overlapping - create hard edges for each color
        // const groupStops = sortedStops.slice(i, groupEnd + 1);
        // const basePos = current.position;

        // // Distribute hard-edge stops across a minimal range
        // groupStops.forEach((stop, idx) => {
        //   const offset = idx * 0.5; // Small offset for each stop
        //   if (idx === 0) {
        //     processedStops.push(`${stop.color} ${basePos}%`);
        //   } else {
        //     // Hard edge: end previous color, start new color at same position
        //     processedStops.push(`${stop.color} ${basePos + offset}%`);
        //   }
        // });

        // i = groupEnd + 1;
        // Multiple stops overlapping - distribute around basePos so no one collapses
        const groupStops = sortedStops.slice(i, groupEnd + 1);
        const basePos = current.position;

        // total width allocated for overlapping group (percent of circle)
        const spread = 1.0; // tweak 0.6–2.0
        const n = groupStops.length;

        let start = basePos - spread / 2;
        let end = basePos + spread / 2;

        // Shift the whole window so it stays in [0, 100]
        if (start < 0) {
          end -= start;     // move right by -start
          start = 0;
        }
        if (end > 100) {
          start -= (end - 100); // move left by (end-100)
          end = 100;
        }
        start = Math.max(0, start); // safety

        const step = n === 1 ? 0 : (end - start) / (n - 1);

        groupStops.forEach((stop, idx) => {
          const pos = start + idx * step;
          processedStops.push(`${stop.color} ${pos}%`);
        });

        i = groupEnd + 1;
      } else {
        // Single stop, no overlap
        processedStops.push(`${current.color} ${current.position}%`);
        i++;
      }
    }

    const stops = processedStops.join(', ');

    switch (gradientType) {
      case 'linear':
        return `linear-gradient(${angle}deg, ${stops})`;
      case 'radial':
        return `radial-gradient(circle, ${stops})`;
      case 'conic':
        return `conic-gradient(from ${angle}deg, ${stops})`;
      default:
        return `linear-gradient(${angle}deg, ${stops})`;
    }
  }, [gradientType, colorStops, angle]);

  const fullCSS = `background: ${gradientCSS};`;

  const copyToClipboard = useCallback(() => {
    navigator.clipboard.writeText(fullCSS);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }, [fullCSS]);

  const randomizeColors = useCallback(() => {
    if (gradientType === 'conic') {
      // For conic gradients, keep first and last colors the same
      setColorStops(prev => {
        const randomColors = prev.map(() => randomColor());
        // Make sure the last color matches the first
        return prev.map((stop, index) => {
          const sortedStops = [...prev].sort((a, b) => a.position - b.position);
          const firstStopId = sortedStops[0].id;
          const lastStopId = sortedStops[sortedStops.length - 1].id;

          if (stop.id === lastStopId) {
            // Last stop gets the same color as first stop
            const firstIndex = prev.findIndex(s => s.id === firstStopId);
            return { ...stop, color: randomColors[firstIndex] };
          }
          return { ...stop, color: randomColors[index] };
        });
      });
    } else {
      setColorStops(prev => prev.map(stop => ({ ...stop, color: randomColor() })));
    }
  }, [gradientType]);

  // Apply a preset palette
  const applyPalette = useCallback((palette) => {
    if (gradientType === 'conic') {
      // For conic gradients, use 4 colors but make first and last the same
      const positions = [0, 33, 67, 100];
      const newStops = palette.colors.map((color, index) => ({
        id: index + 1,
        color: index === 3 ? palette.colors[0] : color, // Last color same as first
        position: positions[index]
      }));
      conicEndpointIdRef.current = 4; // Mark last stop as endpoint
      setColorStops(newStops);
    } else {
      const positions = [0, 33, 67, 100];
      const newStops = palette.colors.map((color, index) => ({
        id: index + 1,
        color: color,
        position: positions[index]
      }));
      setColorStops(newStops);
    }
    setActiveStop(null);
  }, [gradientType]);

  // Get max stops based on gradient type
  const maxStops = gradientType === 'conic' ? 5 : 4;

  // Handle click on gradient bar to add new color stop
  const handleBarClick = useCallback((e) => {
    // Don't add if we just finished dragging or already at max
    if (colorStops.length >= maxStops) return;
    if (isDragging) return;

    const rect = gradientBarRef.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const position = Math.max(0, Math.min(100, (x / rect.width) * 100));

    const newId = Math.max(...colorStops.map(s => s.id)) + 1;
    const newStop = { id: newId, color: randomColor(), position: Math.round(position) };
    setColorStops(prev => [...prev, newStop]);
    setActiveStop(newId);
  }, [colorStops, isDragging, maxStops]);

  // Handle dragging a color stop
  const handleStopMouseDown = useCallback((stopId, e) => {
    e.preventDefault();
    e.stopPropagation();
    draggingIdRef.current = stopId;
    setIsDragging(true);
    setActiveStop(stopId);
  }, []);

  // Global mouse move/up handlers for dragging
  useEffect(() => {
    const handleMouseMove = (e) => {
      if (!draggingIdRef.current || !gradientBarRef.current) return;

      const rect = gradientBarRef.current.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const position = Math.max(0, Math.min(100, (x / rect.width) * 100));

      setColorStops(prev => prev.map(stop => 
        stop.id === draggingIdRef.current 
          ? { ...stop, position: Math.round(position) }
          : stop
      ));
    };

    const handleMouseUp = () => {
      if (draggingIdRef.current) {
        draggingIdRef.current = null;
        // Small delay before allowing bar clicks again
        setTimeout(() => setIsDragging(false), 50);
      }
    };

    // Always attach listeners
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  // Delete a color stop
  const deleteStop = useCallback((stopId) => {
    const minStops = gradientType === 'conic' ? 3 : 2;
    if (colorStops.length <= minStops) return;

    // If deleting the conic endpoint, reassign it to the stop with the highest position (after deletion)
    if (gradientType === 'conic' && stopId === conicEndpointIdRef.current) {
      const remainingStops = colorStops.filter(s => s.id !== stopId);
      const sortedRemaining = [...remainingStops].sort((a, b) => b.position - a.position);
      conicEndpointIdRef.current = sortedRemaining[0]?.id || null;
    }

    setColorStops(prev => prev.filter(stop => stop.id !== stopId));
    setActiveStop(null);
  }, [colorStops, gradientType]);

  // Update active stop color
  const updateStopColor = useCallback((stopId, color) => {
    setColorStops(prev => prev.map(stop => 
      stop.id === stopId ? { ...stop, color } : stop
    ));
  }, []);

  // Track previous gradient type to detect switches
  const prevGradientTypeRef = useRef(gradientType);

  // Track which stop ID is the "endpoint" for conic gradients (should sync with first stop's color)
  const conicEndpointIdRef = useRef(null);

  // When switching TO conic mode, set up default 3-slider configuration
  // When switching FROM conic TO linear/radial, reset to 2 sliders
  useEffect(() => {
    const prevType = prevGradientTypeRef.current;
    prevGradientTypeRef.current = gradientType;

    if (gradientType === 'conic' && prevType !== 'conic') {
      // Switching to conic - set up 3 sliders: ends same color, middle different
      const endColor = randomColor();
      const middleColor = randomColor();
      // Mark id: 3 as the endpoint that will sync with id: 1
      conicEndpointIdRef.current = 3;
      setColorStops([
        { id: 1, color: endColor, position: 0 },
        { id: 2, color: middleColor, position: 50 },
        { id: 3, color: endColor, position: 100 }
      ]);
      setActiveStop(null);
    } else if (gradientType !== 'conic' && prevType === 'conic') {
      // Switching from conic to linear/radial - reset to 2 sliders
      conicEndpointIdRef.current = null;
      setColorStops([
        { id: 1, color: randomColor(), position: 0 },
        { id: 2, color: randomColor(), position: 100 }
      ]);
      setActiveStop(null);
    }
  }, [gradientType]);

  // For conic gradients, the endpoint stop (tracked by ID) syncs its color with the first stop (by position)
  useEffect(() => {
    if (gradientType !== 'conic') return;
    if (!conicEndpointIdRef.current) return;

    const sortedStops = [...colorStops].sort((a, b) => a.position - b.position);
    const firstStop = sortedStops[0];
    const endpointStop = colorStops.find(s => s.id === conicEndpointIdRef.current);

    if (!firstStop || !endpointStop) return;

    // Only sync if the endpoint stop's color differs from the first stop's color
    if (endpointStop.color !== firstStop.color) {
      setColorStops(prev => prev.map(stop => 
        stop.id === conicEndpointIdRef.current 
          ? { ...stop, color: firstStop.color } 
          : stop
      ));
    }
  }, [gradientType, colorStops]);

  const gradientTypes = [
    { value: 'linear', label: 'Linear' },
    { value: 'radial', label: 'Radial' },
    { value: 'conic', label: 'Conic' },
  ];

  if (!tailwindLoaded || !fontsLoaded) {
    return (
      <div style={{ 
        height: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: '#0a0a0a', 
        color: '#c9a962',
        fontFamily: 'serif',
        letterSpacing: '0.2em'
      }}>
        Loading...
      </div>
    );
  }

  // Preview mode - full screen gradient with exit button
  if (previewMode) {
    return (
      <div style={{
        position: 'fixed',
        inset: 0,
        background: gradientCSS,
        fontFamily: "'Playfair Display', serif",
      }}>
        <button
          onClick={() => setPreviewMode(false)}
          style={{
            position: 'absolute',
            top: '32px',
            right: '32px',
            padding: '16px 32px',
            background: 'rgba(0,0,0,0.7)',
            backdropFilter: 'blur(10px)',
            border: '0.5px solid rgba(201,169,98,0.5)',
            borderRadius: '2px',
            color: '#c9a962',
            fontSize: '11px',
            fontFamily: "'Playfair Display', serif",
            letterSpacing: '0.25em',
            cursor: 'pointer',
            textTransform: 'uppercase',
            transition: 'all 0.3s ease'
          }}
          onMouseEnter={(e) => {
            e.target.style.background = 'rgba(201,169,98,0.9)';
            e.target.style.color = '#0a0a0a';
          }}
          onMouseLeave={(e) => {
            e.target.style.background = 'rgba(0,0,0,0.7)';
            e.target.style.color = '#c9a962';
          }}
        >
          Exit Preview
        </button>

        {/* CSS code overlay at bottom */}
        <div style={{
          position: 'absolute',
          bottom: '32px',
          left: '50%',
          transform: 'translateX(-50%)',
          padding: '20px 32px',
          background: 'rgba(0,0,0,0.7)',
          backdropFilter: 'blur(10px)',
          border: '0.5px solid rgba(201,169,98,0.3)',
          borderRadius: '2px',
          fontFamily: 'monospace',
          fontSize: '12px',
          color: '#888',
          maxWidth: '90%',
          textAlign: 'center'
        }}>
          <span style={{ color: '#c9a962' }}>background</span>
          <span style={{ color: '#fafafa' }}>: </span>
