import React from 'react';

const ControlsDisplay = ({ player, side }) => {
  const isP1 = player === 'p1';

  const KeyButton = ({ children, color }) => (
    <div style={{
      display: 'inline-block',
      padding: '6px 10px',
      backgroundColor: '#0a0a0a',
      border: `2px solid ${color}`,
      borderRadius: '0',
      fontSize: '12px',
      fontWeight: '900',
      color: color,
      margin: '2px',
      minWidth: '32px',
      textAlign: 'center',
      boxShadow: `0 0 10px ${color}`,
