          </button>

          {/* VS Divider */}
          <div style={{
            fontSize: '48px',
            fontWeight: '900',
            color: '#FF1493',
            textShadow: '0 0 30px #FF1493',
            letterSpacing: '8px',
            fontFamily: '"Orbitron", sans-serif'
          }}>
            VS
          </div>

          {/* CPU Mode */}
          <button
            onClick={() => handleModeSelect('cpu')}
            onMouseEnter={() => {
              setHoveredMode('cpu');
              if (playSound) playSound('whoosh');
            }}
            onMouseLeave={() => setHoveredMode(null)}
            style={{
              padding: '50px 70px',
              fontSize: '32px',
              fontWeight: '900',
              backgroundColor: hoveredMode === 'cpu' ? '#39FF14' : '#0a0a0a',
              color: hoveredMode === 'cpu' ? '#0a0a0a' : '#39FF14',
              border: '4px solid #39FF14',
              borderRadius: '0',
              cursor: 'pointer',
              transition: 'all 0.3s ease',
              letterSpacing: '4px',
              textTransform: 'uppercase',
              boxShadow: hoveredMode === 'cpu' 
                ? '0 0 60px #39FF14, inset 0 0 30px rgba(57, 255, 20, 0.3)' 
                : '0 0 30px #39FF14, inset 0 0 20px rgba(0, 0, 0, 0.8)',
              clipPath: 'polygon(20px 0, 100% 0, 100% calc(100% - 20px), calc(100% - 20px) 100%, 0 100%, 0 20px)',
              position: 'relative',
              transform: hoveredMode === 'cpu' ? 'scale(1.05) translateY(-5px)' : 'scale(1)',
              textShadow: hoveredMode === 'cpu' ? 'none' : '0 0 20px #39FF14',
              fontFamily: '"Orbitron", sans-serif',
              width: '320px',
              height: '200px',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              gap: '15px'
            }}
          >
            <div style={{ fontSize: '48px', lineHeight: '1' }}>🤖</div>
            <div>CPU</div>
            <div style={{
              fontSize: '14px',
              letterSpacing: '2px',
              opacity: 0.8,
              fontWeight: '600'
            }}>
              AI OPPONENT
            </div>
          </button>
        </div>

        {/* Hint text */}
        <div style={{
          marginTop: '80px',
          fontSize: '14px',
          color: '#00FFFF',
          letterSpacing: '2px',
          fontWeight: '600',
          textShadow: '0 0 10px #00FFFF',
          opacity: 0.7
        }}>
          [[ SELECT YOUR BATTLE MODE ]]
        </div>
      </div>
    </div>
  );
};

export default ModeSelect;

