        {/* Player 1 Controls */}
        <div style={{
          textAlign: 'left'
        }}>
          <h3 style={{
            fontSize: '16px',
            fontWeight: '900',
            color: '#00FFFF',
            marginBottom: '16px',
            letterSpacing: '3px',
            textTransform: 'uppercase',
            textShadow: '0 0 15px #00FFFF',
            fontFamily: '"Orbitron", sans-serif'
