    const packToUse = currentPackPrompts.length > 0 ? currentPackPrompts : prompts;
    const randomPrompt = packToUse[Math.floor(Math.random() * packToUse.length)];
    setGameState(prev => ({
      ...prev,
      currentPrompt: randomPrompt,
      clue: '',
      guessPosition: 50,
